//! Compile-time signature checks for the runtime's `extern "C"` items
//! (roadmap A3): a fn-pointer type maps to its ABI signature through
//! [`AbiFn`], and [`assert_sig`] compares that with a table row inside a
//! `const`, so a disagreement between the table and the implementation is a
//! compile error in `nsl-runtime` that names the function.
//!
//! What is compared is the register class and width of each slot, not the
//! Rust spelling: `u64`, `usize`, `isize` and every raw pointer are the same
//! 64-bit integer slot as `i64` (the rule `abi_from_rust` applies), so an
//! implementation is free to take `*mut T` where the table says `i64`.
//!
//! The runtime's rendering of the table casts each implementation to
//! `unsafe extern "C" fn(_, …) -> _` and passes it here; `_` lets `rustc`
//! infer the implementation's own parameter types, which is what makes the
//! check see the real signature rather than the table's expectation.

use crate::AbiScalar;

/// The ABI slot a Rust parameter type occupies.
pub trait AbiScalarOf {
    /// The register class and width.
    const SCALAR: AbiScalar;
}

/// The ABI slot a Rust return type occupies; `None` for `()`.
pub trait AbiRetOf {
    /// The register class and width, or `None` for no return value.
    const RET: Option<AbiScalar>;
}

macro_rules! scalar_impls {
    ($($t:ty => $s:expr;)*) => { $(
        impl AbiScalarOf for $t { const SCALAR: AbiScalar = $s; }
        impl AbiRetOf for $t { const RET: Option<AbiScalar> = Some($s); }
    )* };
}
scalar_impls! {
    i8 => AbiScalar::Int(8); u8 => AbiScalar::Int(8); bool => AbiScalar::Int(8);
    i16 => AbiScalar::Int(16); u16 => AbiScalar::Int(16);
    i32 => AbiScalar::Int(32); u32 => AbiScalar::Int(32);
    i64 => AbiScalar::Int(64); u64 => AbiScalar::Int(64); isize => AbiScalar::Int(64); usize => AbiScalar::Int(64);
    f32 => AbiScalar::Float(32); f64 => AbiScalar::Float(64);
}
impl<T> AbiScalarOf for *const T { const SCALAR: AbiScalar = AbiScalar::Int(64); }
impl<T> AbiScalarOf for *mut T { const SCALAR: AbiScalar = AbiScalar::Int(64); }
impl<T> AbiRetOf for *const T { const RET: Option<AbiScalar> = Some(AbiScalar::Int(64)); }
impl<T> AbiRetOf for *mut T { const RET: Option<AbiScalar> = Some(AbiScalar::Int(64)); }
impl AbiRetOf for () { const RET: Option<AbiScalar> = None; }

/// The ABI signature of an `unsafe extern "C"` fn-pointer type. Implemented
/// for every arity up to 64.
pub trait AbiFn {
    /// Parameter slots, in order.
    const PARAMS: &'static [AbiScalar];
    /// Return slot, or `None`.
    const RET: Option<AbiScalar>;
}

impl<R: AbiRetOf> AbiFn for unsafe extern "C" fn() -> R {
    const PARAMS: &'static [AbiScalar] = &[];
    const RET: Option<AbiScalar> = R::RET;
}
impl<A0: AbiScalarOf, R: AbiRetOf> AbiFn for unsafe extern "C" fn(A0) -> R {
    const PARAMS: &'static [AbiScalar] = &[A0::SCALAR];
    const RET: Option<AbiScalar> = R::RET;
}
impl<A0: AbiScalarOf, A1: AbiScalarOf, R: AbiRetOf> AbiFn for unsafe extern "C" fn(A0, A1) -> R {
    const PARAMS: &'static [AbiScalar] = &[A0::SCALAR, A1::SCALAR];
    const RET: Option<AbiScalar> = R::RET;
}
