/// Structural equality on [`AbiScalar`], usable in `const`.
pub const fn scalar_eq(a: AbiScalar, b: AbiScalar) -> bool {
    match (a, b) {
        (AbiScalar::Int(x), AbiScalar::Int(y)) => x == y,
        (AbiScalar::Float(x), AbiScalar::Float(y)) => x == y,
        _ => false,
    }
}

/// `true` when two signatures agree slot for slot.
pub const fn sig_eq(
    params_a: &[AbiScalar],
    ret_a: Option<AbiScalar>,
    params_b: &[AbiScalar],
    ret_b: Option<AbiScalar>,
) -> bool {
    if params_a.len() != params_b.len() {
        return false;
    }
    let mut i = 0;
    while i < params_a.len() {
        if !scalar_eq(params_a[i], params_b[i]) {
            return false;
        }
        i += 1;
    }
    match (ret_a, ret_b) {
        (None, None) => true,
        (Some(x), Some(y)) => scalar_eq(x, y),
        _ => false,
    }
}

/// Compile-time assertion that `f`'s signature is `params -> ret`. Called
/// from a `const` item; on disagreement the build fails with `name`.
pub const fn assert_sig<F: AbiFn + Copy>(
    _f: F,
    name: &str,
    params: &[AbiScalar],
    ret: Option<AbiScalar>,
) {
    if !sig_eq(F::PARAMS, F::RET, params, ret) {
        panic!("{}", name);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    extern "C" fn two(_a: u64, _p: *mut u8) -> i64 {
        0
    }
    unsafe extern "C" fn none() {}

    #[test]
    fn pointers_and_unsigned_are_i64_slots() {
        type F = unsafe extern "C" fn(u64, *mut u8) -> i64;
        assert_eq!(<F as AbiFn>::PARAMS, &[AbiScalar::Int(64), AbiScalar::Int(64)]);
        assert_eq!(<F as AbiFn>::RET, Some(AbiScalar::Int(64)));
        const _: () = assert_sig(
            two as unsafe extern "C" fn(_, _) -> _,
            "two",
            &[AbiScalar::Int(64), AbiScalar::Int(64)],
            Some(AbiScalar::Int(64)),
        );
        const _: () = assert_sig(none as unsafe extern "C" fn() -> _, "none", &[], None);
    }

    #[test]
    fn sig_eq_is_slotwise() {
        let i = AbiScalar::Int(64);
        let f = AbiScalar::Float(64);
        assert!(sig_eq(&[i, f], Some(i), &[i, f], Some(i)));
        assert!(!sig_eq(&[i, f], Some(i), &[f, i], Some(i)));
        assert!(!sig_eq(&[i], None, &[i], Some(i)));
        assert!(!sig_eq(&[i], None, &[i, i], None));
    }
}
